// Modifiers describes keyboard modifiers held with a key.
type Modifiers uint32

const (
	ModifierShift   Modifiers = 0x1
	ModifierControl Modifiers = 0x2
	ModifierAlt     Modifiers = 0x4
	// The Super or Windows key.
	ModifierLogo Modifiers = 0x8
)

// String names the flags set in value, joined by "|".
func (value Modifiers) String() string {
	if value == 0 {
		return "0"
	}
	var names []string
	for _, flag := range [...]struct {
		value Modifiers
		name  string
	}{
		{ModifierShift, "ModifierShift"},
		{ModifierControl, "ModifierControl"},
		{ModifierAlt, "ModifierAlt"},
		{ModifierLogo, "ModifierLogo"},
	} {
		if value&flag.value != 0 {
			names = append(names, flag.name)
			value &^= flag.value
		}
	}
	if value != 0 {
		names = append(names, fmt.Sprintf("%#x", uint32(value)))
	}
	return strings.Join(names, "|")
}

// Error describes the status, so a Status serves as an error value: compare a
// returned error with a status constant through errors.Is.
func (status Status) Error() string {
	switch status {
	case StatusOK:
		return "rikka: ok"
	case StatusNoDisplay:
		return "rikka: no display"
	case StatusGPU:
		return "rikka: gpu"
	case StatusSystem:
		return "rikka: system"
	case StatusClosed:
		return "rikka: closed"
	case StatusCancelled:
		return "rikka: cancelled"
	case StatusFailed:
		return "rikka: failed"
	}
	return fmt.Sprintf("rikka: status %d", uint32(status))
}

// Error is an operation that failed at run time: its [Status] and what went wrong.
// It unwraps to its status.
type Error struct {
	Status  Status
	Message string
}

func (failure *Error) Error() string {
	if failure.Message == "" {
		return failure.Status.Error()
	}
	return "rikka: " + failure.Message
}

// Unwrap returns the failing status.
func (failure *Error) Unwrap() error {
	return failure.Status
}

func checkStatus(status C.rk_status) error {
	if Status(status) == StatusOK {
		return nil
	}
	return &Error{Status: Status(status), Message: goString(C.rk_last_error())}
}

func statusError(status Status) error {
	if status == StatusOK {
		return nil
	}
	return status
}

// App is an application: its identity and first windows.
//
// It owns its native object until it is handed over; the garbage collector frees an object
// never handed over.
type App struct {
	raw     *C.rk_app
	cleanup runtime.Cleanup
}

func newApp(raw *C.rk_app) *App {
	if raw == nil {
		panic(unmade("App"))
	}
	value := &App{raw: raw}
	value.cleanup = runtime.AddCleanup(value, func(raw *C.rk_app) { C.rk_app_free(raw) }, raw)
	return value
}

func (x *App) handle() *C.rk_app {
	if x == nil || x.raw == nil {
		panic(consumed("App"))
	}
	return x.raw
}

func (x *App) take() *C.rk_app {
	raw := x.handle()
	x.cleanup.Stop()
	x.raw = nil
	return raw
}

// NewApp makes an application.
//
//   - id: The reverse-DNS application id, such as org.example.notes; it names the desktop entry and
//     the bus name on Linux, and the AppUserModelID and instance pipe on Windows.
func NewApp(id string) *App {
	return newApp(C.rk_app_new(cStr(id)))
}

// SingleInstance makes later starts hand their arguments to the running instance's
// [WindowBuilder.OnLaunch] callback instead of starting anew.
func (a *App) SingleInstance(single bool) *App {
	C.rk_app_set_single_instance(a.handle(), C.bool(single))
	runtime.KeepAlive(a)
	return a
}

// AddWindow adds a window opened when the application starts.
//
//   - window: It is consumed.
func (a *App) AddWindow(window *WindowBuilder) *App {
	windowRaw := window.take()
	C.rk_app_add_window(a.handle(), windowRaw)
	runtime.KeepAlive(a)
	return a
}

// Run runs the application on the calling thread until its last window closes.
//
// It returns an [*Error] carrying the failing status.
func (a *App) Run() error {
	raw := a.take()
	return checkStatus(C.rk_app_run(raw))
}

