// Window is an open window.
//
// It holds one reference to a native object usable from any goroutine; the garbage collector
// drops the reference.
type Window struct {
	raw     *C.rk_window
	cleanup runtime.Cleanup
}

func newWindow(raw *C.rk_window) *Window {
	if raw == nil {
		panic(unmade("Window"))
	}
	value := &Window{raw: raw}
	value.cleanup = runtime.AddCleanup(value, func(raw *C.rk_window) { C.rk_window_unref(raw) }, raw)
	return value
}

func (x *Window) handle() *C.rk_window {
	if x == nil || x.raw == nil {
		panic(consumed("Window"))
	}
	return x.raw
}

// Invalidate runs the window's view again soon, after state changed outside a callback.
//
// Thread-safe.
func (w *Window) Invalidate() {
	C.rk_window_invalidate(w.handle())
	runtime.KeepAlive(w)
}

// Post runs a callback on the application thread with the window's context; the view runs again
// afterwards.
//
// Thread-safe.
//
//   - callback: Reacts to an event. The window's view runs again afterwards unless
//     [Context.SkipView] is called. It may run on any thread.
//
// It returns [StatusOK], or [StatusClosed] if the window is gone; the callback then never runs.
func (w *Window) Post(callback func(context *Context)) error {
	if callback == nil {
		panic("rikka: callback is nil")
	}
	userdata := retain(callback)
	result := statusError(Status(C.rk_window_post(w.handle(), C.rk_action_fn(C.rikkaActionFn0), userdata, C.rk_destroy_fn(C.rikkaDestroy))))
	runtime.KeepAlive(w)
	return result
}

