// Element is the element declared last, which its modifiers change. Chain them right away: the
// next declared element becomes the current one, and a modifier of an older element panics.
type Element struct {
	view   *View
	serial uint64
}

func (e Element) current() *C.rk_view {
	raw := e.view.handle()
	if e.serial != e.view.serial {
		panic("rikka: modifiers apply only to the element declared last")
	}
	return raw
}

