// Version returns the version of the loaded library, packed as major << 22 | minor << 12 |
// patch.
//
// Thread-safe.
func Version() uint32 {
	return uint32(C.rk_version())
}

// LastError describes the last failure on the calling thread.
//
// Thread-safe.
//
// It returns valid until the next failing call on this thread; empty if nothing failed.
func LastError() string {
	return goString(C.rk_last_error())
}

// OpenURL opens a web address in the desktop's browser, or another URL in the program that
// handles its scheme, such as mailto: in the mail program.
//
// Thread-safe.
//
//   - url: An absolute URL such as https://example.org.
//
// It returns an [*Error] carrying the failing status.
func OpenURL(url string) error {
	return checkStatus(C.rk_open_url(cStr(url)))
}

// OpenFile opens a file or folder in the desktop's default program for it.
//
// Thread-safe.
//
//   - path: Absolute, or relative to the working directory.
//
// It returns an [*Error] carrying the failing status.
func OpenFile(path string) error {
	return checkStatus(C.rk_open_file(cStr(path)))
}

// TextWidth how wide one line of text is when [View.Text] draws it with [Element.TextSize] and
// no other text styling, in logical pixels.
//
//   - size: The text size in logical pixels; above 0.
func TextWidth(text string, size float32) float32 {
	return float32(C.rk_text_width(cStr(text), C.float(size)))
}
